fun findUniqueCharacters(input: String): List<Char> {
    return input.filter { char -> input.count { it == char } == 1 }.distinct()
}

fun findUniqueCharacters(input: String): List<Char> {
    val counts = input.groupingBy { it }.eachCount()
    return input.filter { counts[it] == 1 }.distinct()
}

fun findUniqueCharacters(input: String): List<Char> {
    val counts = mutableMapOf<Char, Int>()
    for (char in input) counts[char] = (counts[char] ?: 0) + 1
    return input.filter { counts[it] == 1 }.distinct()

}

fun findUniqueCharacters(input: String): List<Char> {
    return input.asSequence().filter { char -> input.count { it == char } == 1 }.distinct().toList()
}
